function validate([original, m, n]) {
  if (!Array.isArray(original) || original.length < 1 || original.length > 50000) return 'original needs 1 to 5 * 10^4 values.';
  if (original.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value in original is an integer from 1 to 10^5.';
  if (!Number.isInteger(m) || m < 1 || m > 40000) return 'm is an integer from 1 to 4 * 10^4.';
  if (!Number.isInteger(n) || n < 1 || n > 40000) return 'n is an integer from 1 to 4 * 10^4.';
  return null;
}

