function construct2DArray(original, m, n) {
  if (m * n !== original.length) {
    return [];
  }
  const grid = [];
  let index = 0;

  for (let row = 0; row < m; row++) {
    const currentRow = [];
    for (let col = 0; col < n; col++) {
      currentRow.push(original[index]);
      index++;
    }
    grid.push(currentRow);
  }
