function construct2DArray(original, m, n) {
  const cells = m * n;
  if (cells !== original.length) return [];
  const grid = Array.from({ length: m }, () => new Array(n));
  for (let i = 0; i < cells; i++) grid[Math.floor(i / n)][i % n] = original[i];
  return grid;
}

