function generate(rand, size) {
  const length = size === 'large' ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 12);
  const top = size === 'large' ? 100000 : 20;
  const original = Array.from({ length }, () => 1 + Math.floor(rand() * top));
  const divisors = [];
  for (let d = 1; d <= length; d++) if (length % d === 0) divisors.push(d);
  let m, n;
  if (rand() < 0.75) {
    m = divisors[Math.floor(rand() * divisors.length)];
    n = length / m;
  } else {
    const limit = size === 'large' ? 40000 : 6;
    do {
      m = 1 + Math.floor(rand() * limit);
      n = 1 + Math.floor(rand() * limit);
    } while (m * n === length);
  }
  return [original, m, n];
}
